def sequential_search(arr, element):
    """
    Searches for an element in a list using linear search.

    Args:
        arr: The list/array to search within.
        element: The element to find.

    Returns:
        A tuple (found, index) where found is True/False and index is the position 
        or -1 if not found.
    """
    for i in range(len(arr)):
        if arr[i] == element:
            return (True, i)

    return (False, -1)
