def check_expression(expression):
    stack = []
    opening_brackets = {'(', '{', '['}
    closing_brackets_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets_map:
            if not stack or stack[-1] != closing_brackets_map[char]:
                return False
            stack.pop()

    return len(stack) == 0

# Verify the solution with the provided test case
assert check_expression("{()}[{}]") == True
```

